class BckApiClient{BckApiClient({Dio?dio}):_dio=dio??Dio(BaseOptions(baseUrl:AppConfig.apiBaseUrl,connectTimeout:const Duration(seconds:10),receiveTimeout:const Duration(seconds:10),headers:const{'Accept':'application/json'}));final Dio _dio;String?_accessToken;void setAccessToken(String?token)=>_accessToken=token;Options get _authorizedOptions=>Options(headers:_accessToken==null?null:{'Authorization':'Bearer $_accessToken'});Future<ApiHealth>health()async=>ApiHealth.fromJson((await _dio.get<Map<String,dynamic>>('/api/v1/health')).data!);Future<BootstrapCompanyResponse>createCompany(BootstrapCompanyRequest r)async=>BootstrapCompanyResponse.fromJson((await _dio.post<Map<String,dynamic>>('/api/v1/bootstrap/company',data:r.toJson())).data!);Future<PairingCode>createPairingCode(String deviceMode)async=>PairingCode.fromJson((await _dio.post<Map<String,dynamic>>('/api/v1/devices/pair',data:{'deviceMode':deviceMode},options:_authorizedOptions)).data!);Future<List<DeviceItem>>devices()async{final r=await _dio.get<List<dynamic>>('/api/v1/devices',options:_authorizedOptions);return r.data!.map((e)=>DeviceItem.fromJson(Map<String,dynamic>.from(e))).toList();}Future<void>changeDeviceMode(String deviceId,String deviceMode)async=>_dio.patch<void>('/api/v1/devices/$deviceId/mode',data:{'deviceMode':deviceMode},options:_authorizedOptions);Future<void>revokeDevice(String deviceId)async=>_dio.post<void>('/api/v1/devices/$deviceId/revoke',options:_authorizedOptions);Future<List<ManagedUserItem>>users()async{final r=await _dio.get<List<dynamic>>('/api/v1/users',options:_authorizedOptions);return r.data!.map((e)=>ManagedUserItem.fromJson(Map<String,dynamic>.from(e))).toList();}Future<void>createUser({required String name,String?phone,String?functionName,required String profile,required bool servesClients,required String username,required String password,required List<String>permissions})async=>_dio.post<void>('/api/v1/users',data:{'name':name,'phone':phone,'functionName':functionName,'profile':profile,'servesClients':servesClients,'username':username,'password':password,'permissions':permissions},options:_authorizedOptions);Future<void>updateUser(String id,{required String name,String?phone,String?functionName,required String profile,required bool servesClients,required bool active,required List<String>permissions})async=>_dio.put<void>('/api/v1/users/$id',data:{'name':name,'phone':phone,'functionName':functionName,'profile':profile,'servesClients':servesClients,'active':active,'permissions':permissions},options:_authorizedOptions);Future<void>resetUserPassword(String id,String password)async=>_dio.post<void>('/api/v1/users/$id/reset-password',data:{'password':password},options:_authorizedOptions);Future<PairingResult>pairDevice({required String pairingCode,required String deviceId,required String deviceName,required String username,required String password})async=>PairingResult.fromJson((await _dio.post<Map<String,dynamic>>('/api/v1/devices/pair/consume',data:{'pairingCode':pairingCode,'deviceId':deviceId,'deviceName':deviceName,'platform':'ANDROID','username':username,'password':password})).data!);Future<AuthSession>login({required String groupId,required String username,required String password,required String deviceId})async{final s=AuthSession.fromJson((await _dio.post<Map<String,dynamic>>('/api/v1/auth/login',data:{'groupId':groupId,'username':username,'password':password,'deviceId':deviceId})).data!);setAccessToken(s.accessToken);return s;}Future<RefreshedTokens>refresh(String token)async{final r=RefreshedTokens.fromJson((await _dio.post<Map<String,dynamic>>('/api/v1/auth/refresh',data:{'refreshToken':token})).data!);setAccessToken(r.accessToken);return r;}Future<void>logout(String token)async{await _dio.post<void>('/api/v1/auth/logout',data:{'refreshToken':token});setAccessToken(null);}Future<Map<String,dynamic>>me()async=>(await _dio.get<Map<String,dynamic>>('/api/v1/auth/me',options:_authorizedOptions)).data!;Future<List<ClientItem>>clients(String groupId,{String query=''})async{final r=await _dio.get<List<dynamic>>('/api/v1/clients',queryParameters:{'q':query},options:_authorizedOptions);return r.data!.map((e)=>ClientItem.fromJson(Map<String,dynamic>.from(e))).toList();}Future<List<ServiceItem>>services(String groupId)async{final r=await _dio.get<List<dynamic>>('/api/v1/services',options:_authorizedOptions);return r.data!.map((e)=>ServiceItem.fromJson(Map<String,dynamic>.from(e))).toList();}Future<List<AppointmentItem>>appointments({required String groupId,required String professionalUserId,required DateTime from,required DateTime to})async{final r=await _dio.get<List<dynamic>>('/api/v1/appointments',queryParameters:{'professionalUserId':professionalUserId,'from':from.toUtc().toIso8601String(),'to':to.toUtc().toIso8601String()},options:_authorizedOptions);return r.data!.map((e)=>AppointmentItem.fromJson(Map<String,dynamic>.from(e))).toList();}Future<bool>availability({required String groupId,required String professionalUserId,required DateTime startsAt,required DateTime endsAt})async{final r=await _dio.get<Map<String,dynamic>>('/api/v1/appointments/availability',queryParameters:{'professionalUserId':professionalUserId,'startsAt':startsAt.toUtc().toIso8601String(),'endsAt':endsAt.toUtc().toIso8601String()},options:_authorizedOptions);return r.data!['available']as bool;}Future<AppointmentItem>createAppointment({required String groupId,required String professionalUserId,required String createdByUserId,String?clientId,String?walkInName,String?walkInPhone,required String serviceId,required DateTime startsAt,required int durationMinutes,bool isFitIn=false,bool forceConflict=false,String?notes})async{final r=await _dio.post<Map<String,dynamic>>('/api/v1/appointments',data:{'professionalUserId':professionalUserId,'clientId':clientId,'walkInName':walkInName,'walkInPhone':walkInPhone,'serviceId':serviceId,'startsAt':startsAt.toUtc().toIso8601String(),'durationMinutes':durationMinutes,'isFitIn':isFitIn,'forceConflict':forceConflict,'notes':notes},options:_authorizedOptions);return AppointmentItem.fromJson(r.data!);}}
